insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g3_science_v1'
from (values
('112.5.b.6.A',2,'Which tool measures the mass of a rock?','["a balance", "a rain gauge", "a thermometer", "a ruler"]'::jsonb,0,'A balance compares or measures mass.','original'),
('112.5.b.6.A',2,'Which tool should a student use to find the temperature of warm water?','["a magnet", "a thermometer", "a hand lens", "a balance"]'::jsonb,1,'A thermometer measures temperature.','original'),
('112.5.b.6.A',3,'A student drops a wooden block and a steel nut in water. The block floats and the nut sinks. What property was tested?','["temperature", "color", "ability to sink or float", "magnetism"]'::jsonb,2,'The test showed which objects sink or float in water.','original'),
('112.5.b.6.A',3,'A student holds a magnet near a steel paper clip, a plastic spoon, and a wooden stick. Which is pulled to the magnet?','["the spoon", "the stick", "none of them", "the paper clip"]'::jsonb,3,'Steel is attracted to magnets, and plastic and wood are not.','original'),
('112.5.b.6.A',3,'Three rocks have masses of 20 g, 55 g, and 35 g. Which has the greatest mass?','["the 55 g rock", "they all have the same", "the 20 g rock", "the 35 g rock"]'::jsonb,0,'55 g is the greatest mass.','original'),
('112.5.b.6.A',3,'Water in a cup measures 20°C at 9:00 and 28°C at 11:00. What happened to the water?','["it got colder", "it got warmer", "it stayed the same", "it turned to ice"]'::jsonb,1,'A higher temperature means it got warmer.','original'),
('112.5.b.6.A',4,'A student wants to know if a coin is magnetic. What should the student do?','["measure the coin''s color", "weigh the coin", "hold a magnet near the coin", "put the coin in water"]'::jsonb,2,'A magnet test shows if an object is magnetic.','original'),
('112.5.b.6.B',2,'Which state of matter keeps its own shape?','["a gas", "a liquid", "none of them", "a solid"]'::jsonb,3,'A solid has a definite shape.','original'),
('112.5.b.6.B',2,'Juice is poured from a tall glass into a wide bowl. What happens to the juice?','["it takes the shape of the bowl", "it disappears", "it keeps the glass shape", "it turns into a solid"]'::jsonb,0,'A liquid takes the shape of its container.','original'),
('112.5.b.6.B',3,'Which of these is a gas?','["a puddle", "the air in a balloon", "a rock", "a metal key"]'::jsonb,1,'Air is a gas.','original'),
('112.5.b.6.B',3,'Which state of matter fills its whole container and spreads out?','["a solid", "ice", "a gas", "a liquid"]'::jsonb,2,'Gases spread to fill all the space available.','original'),
('112.5.b.6.B',3,'A student puts the same amount of water into a tall cup and a short, wide cup. What stays the same?','["the shape of the water", "the height of the water", "the look of the water", "the amount of water"]'::jsonb,3,'The amount of water is the same, but the shape changes with the container.','original'),
('112.5.b.6.B',3,'Which list contains a solid, a liquid, and a gas in that order?','["ice, milk, steam", "ice, steam, milk", "milk, ice, steam", "steam, milk, ice"]'::jsonb,0,'Ice is a solid, milk is a liquid, and steam is a gas.','original'),
('112.5.b.6.B',4,'Which is NOT true of a solid?','["it keeps its shape on a table", "it takes the shape of any container", "it has a definite shape", "it has a definite volume"]'::jsonb,1,'Solids keep their shape. Liquids and gases take the shape of a container.','original'),
('112.5.b.6.C',2,'What happens to an ice cube in a warm room?','["it becomes a rock", "it turns into a gas at once", "it melts into liquid water", "it stays the same"]'::jsonb,2,'Heat makes ice melt into water.','original'),
('112.5.b.6.C',3,'Water droplets form on the outside of a cold glass on a hot day. What is this called?','["freezing", "melting", "evaporation", "condensation"]'::jsonb,3,'Water vapor in the air cools and turns into liquid water.','original'),
('112.5.b.6.C',3,'A pot of water is heated until it bubbles and makes steam. What state of matter is steam?','["a gas", "a metal", "a solid", "a liquid"]'::jsonb,0,'Heating water can turn it into water vapor, a gas.','original'),
('112.5.b.6.C',3,'A puddle on a sunny sidewalk gets smaller and smaller. What is happening?','["the water is freezing", "the water is evaporating", "the water is melting", "the water is turning to rock"]'::jsonb,1,'Heat from the Sun turns liquid water into water vapor.','original'),
('112.5.b.6.C',2,'Liquid water is put in a freezer. What does it become?','["steam", "soil", "ice", "vapor"]'::jsonb,2,'Cooling a liquid enough makes it freeze into a solid.','original'),
('112.5.b.6.C',3,'A student predicts that melted chocolate will become solid again in the refrigerator. Why?','["the refrigerator adds heat", "heating makes liquids harden", "cold makes solids melt", "cooling makes liquids freeze or harden"]'::jsonb,3,'Taking away heat makes the chocolate harden.','original'),
('112.5.b.6.C',4,'Which sequence shows water changing from liquid to solid to liquid?','["water, ice, water", "steam, water, ice", "ice, steam, water", "water, steam, ice"]'::jsonb,0,'Freezing then melting changes water from a liquid to a solid and back.','original'),
('112.5.b.6.D',2,'Why might a builder use steel to build a bridge?','["it floats on air", "it is strong", "it is soft", "it melts easily"]'::jsonb,1,'Steel is strong and can hold weight.','original'),
('112.5.b.6.D',3,'A student adds clay to sand to make a brick. Why?','["the clay makes the sand disappear", "the clay makes the sand lighter", "the clay helps hold the sand together", "the clay makes the brick melt"]'::jsonb,2,'Clay sticks the sand grains together and makes a stronger brick.','original'),
('112.5.b.6.D',3,'A student needs a material for a raincoat. Which property matters most?','["it is magnetic", "it is loud", "it is shiny", "it keeps water out"]'::jsonb,3,'A raincoat should block water.','original'),
('112.5.b.6.D',3,'A student needs a cup that will keep a drink warm. Which material is best?','["foam", "thin metal", "paper towel", "wire mesh"]'::jsonb,0,'Foam slows the loss of heat.','original'),
('112.5.b.6.D',3,'Which two materials could a student combine to make a stronger, harder building block?','["water and air", "sand and clay", "feathers and foam", "paper and tissue"]'::jsonb,1,'Sand and clay combine to make a harder brick.','original'),
('112.5.b.6.D',3,'A student builds a tower with straws. Which choice makes the tower stronger?','["use bent straws only", "leave the straws loose", "tape the straws together at the joints", "use fewer straws"]'::jsonb,2,'Taping joints holds parts together.','original'),
('112.5.b.6.D',4,'A student must pick a material for an insulating lunch bag. Which property should be tested?','["how loud it sounds", "how shiny it looks", "how magnetic it is", "how well it keeps heat from passing through"]'::jsonb,3,'Insulation depends on how well heat is blocked.','original'),
('112.5.b.7.A',2,'What force pulls a dropped ball toward the ground?','["gravity", "magnetism", "friction only", "light"]'::jsonb,0,'Gravity pulls objects toward Earth.','original'),
('112.5.b.7.A',3,'A magnet pulls a paper clip without touching it. What kind of force is this?','["no force", "a force at a distance", "a sound", "a force that needs touching"]'::jsonb,1,'Magnetic force can act without contact.','original'),
('112.5.b.7.A',2,'A student kicks a soccer ball. What kind of force is a kick?','["magnetism", "gravity", "a push", "a pull"]'::jsonb,2,'Kicking pushes the ball.','original'),
